    slug: "pool-015",
    title: "天然vs化学成分：药师的实用小课堂",
    kicker: "Ingredient lab",
    category: "Supplement",
    date: "21 Dec 2025",
    readTime: "4 min",
    excerpt: "最近很多人问我天然vs化学成分的问题，今天一次讲清楚。",
    cover: "/products/epsilon-cream-1.png",
    accent: "#a62f4f",
    body: [
      { text: "最近很多人问我天然vs化学成分的问题，今天一次讲清楚。" },
      { heading: "天然成分 vs 化学成分的真相", text: "「天然的就是好的，化学的就是坏的」——这是最大的护肤迷思之一。砷、汞、铅都是天然的，但你不会想把它们涂在脸上。水杨酸最初来自柳树皮（天然），但现在通过合成可以获得更纯更稳定的版本。关键不是「天然」还是「化学」，而是：这个成分是否安全？浓度是否合适？配方是否稳定？是否经过测试？很多「纯天然」产品反而更容易引起过敏（精油、花粉等天然过敏原）。" },
      { heading: "蛋白质——从运动到抗老的必需品", text: "蛋白质是肌肉修复和生长的基础。运动后 30-60 分钟内摄取蛋白质可以最大化肌肉修复效果。随着年龄增长，身体对蛋白质的利用效率下降，老年人每天建议摄取约 1.0-1.2g 每公斤体重的蛋白质。亚洲饮食普遍以碳水为主，很多人长期蛋白质摄取不足，这会加速肌肉流失。优质蛋白质来源包括鸡蛋、鱼类、鸡肉、牛奶和豆制品。不需要大量补充，但每餐都应该有足够的蛋白质。" },
      { heading: "成分党入门指南", text: "想看懂护肤品成分表（INCI）其实不难：成分按浓度从高到低排列，前 5 个通常占了产品的大部分。所以如果一个产品号称含有某种神奇成分但排在防腐剂后面，那浓度大概很低。但也要注意：有些成分在很低浓度下就有效（如视黄醇 0.3%），所以不是越高越好。学会看成分表可以帮助你避免被夸张的营销骗到，找到真正适合自己的产品。不需要成为化学家，但了解基础知识就够了。" },
      { heading: "天然vs化学成分小结", text: "✅ Marketing——这是一个值得关注的方向。\n🔹 Safety——这是一个值得关注的方向。\n✅ Myth——这是一个值得关注的方向。" },
      { heading: "药师小贴士 💊", text: "药师小贴士 💊 每个人的体质不同，适合别人的不一定适合你。" },
      { text: "你有什么心得？欢迎在留言区分享。" },
    ],
